const ShopCategory = (props) => {
  const { all_products } = useContext(ShopContext);
  return (
    <div className='shop-category'>
      <img src={mens_banner} alt="Men's Banner" />
      {all_products.map(product => (
        <div key={product.id}>
          <h3>{product.name}</h3>
          <p>${product.price}</p>
        </div>
      ))}
    </div>
  );
}
